#include <nlohmann/json.hpp>
#include <array>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
using J=nlohmann::json;
J read(const char* path){if(std::filesystem::file_size(path)>32*1024*1024)throw std::runtime_error("family report bound");std::ifstream f(path);return J::parse(f);}
int main(int argc,char**argv){try{if(argc!=4||std::filesystem::exists(argv[3]))throw std::runtime_error("usage: family_verify BEFORE AFTER FRESH_REPORT");const auto before=read(argv[1]),after=read(argv[2]);J checks=J::array(),rows=J::array();int failed=0;auto check=[&](std::string id,bool pass){checks.push_back({{"id",std::move(id)},{"pass",pass}});failed+=!pass;};
 check("same_predeclared_family",before.at("plan_sha256")==after.at("plan_sha256"));check("complete_declared_run_matrix",before.at("runs").size()==12&&after.at("runs").size()==12);
 for(std::size_t i=0;i<after.at("runs").size();++i){const auto&a=after.at("runs")[i],&b=before.at("runs")[i];const std::string id=std::to_string(i)+"_"+a.at("mode").get<std::string>()+"_"+a.at("control").get<std::string>();check(id+"_same_input_cell",a.at("mode")==b.at("mode")&&a.at("offset")==b.at("offset")&&a.at("control")==b.at("control")&&a.at("requested")==b.at("requested"));check(id+"_full_input_denominator",a.at("processed")==a.at("requested")&&a.at("frames").size()==a.at("requested"));check(id+"_safety_and_release",a.at("safe")==true&&a.at("release_verified")==true&&a.at("ledger_valid")==true&&a.at("active_final")==0);
  bool frame_order=true;int f=0;for(const auto&frame:a.at("frames"))frame_order&=frame.at("frame")==++f&&frame.at("safe")==true;check(id+"_all_frame_order",frame_order);
  std::array<int,3> phases{},measured{};std::array<bool,5> active{};std::map<unsigned long long,unsigned long long> intent_note;std::set<unsigned long long> down_intents;bool joined=true,contact_safe=true,ordered=true;int normal=0,tail_confirmed=0,cancelled=0;
  for(const auto&e:a.at("owner_events")){const auto type=e.at("event").get<std::string>();if(type=="own_accepted_plan"){const auto intent=e.at("intent").get<unsigned long long>(),note=e.at("note").get<unsigned long long>();if(intent_note.contains(intent))joined&=intent_note[intent]==note;intent_note[intent]=note;}normal+=type=="game_contact_up"&&e.value("reason","")=="visible_tail_completed";tail_confirmed+=type=="game_hold_tail_confirmed";cancelled+=type=="game_contact_cancelled";}
  for(const auto&e:a.at("receipts")){if(e.at("event")=="release"){for(int c:e.at("requested")){if(c<0||c>=5){contact_safe=false;continue;}active[c]=false;}contact_safe&=e.at("failed").empty()&&e.at("unknown").empty();continue;}int p=e.at("phase"),c=e.at("contact");if(p<0||p>2||c<0||c>=5){contact_safe=false;continue;}++phases[p];if(e.at("dispatch_frame").get<int>()>256)++measured[p];const auto intent=e.at("intent").get<unsigned long long>();joined&=intent_note.contains(intent);ordered&=e.at("return")>=e.at("start")&&e.at("success")==true;if(p==0){contact_safe&=!active[c]&&down_intents.insert(intent).second;active[c]=true;}else{contact_safe&=active[c];if(p==2)active[c]=false;}}
  for(bool held:active)contact_safe&=!held;check(id+"_complete_phase_receipts",J(phases)==a.at("phase_counts")&&J(measured)==a.at("measurement_phase_counts"));check(id+"_own_plan_receipt_join",joined);check(id+"_sole_owner_contact_lifetime",contact_safe&&ordered);
  std::size_t bbody=0,abody=0;for(const auto&frame:b.at("frames"))for(const auto&s:frame.at("support"))bbody+=s.at("accepted")==true&&s.at("active")==true&&s.at("body")==true;for(const auto&frame:a.at("frames"))for(const auto&s:frame.at("support"))abody+=s.at("accepted")==true&&s.at("active")==true&&s.at("body")==true;
  const bool positive=a.at("control")=="positive";if(positive){check(id+"_repeated_distinct_own_holds",phases[0]==8&&phases[2]==8&&down_intents.size()==8&&a.at("distinct_notes").size()==8);check(id+"_measurement_action_nonempty",measured[0]==4&&measured[2]==4);if(a.at("mode")=="B")check(id+"_body_support_improved",abody>bbody);else check(id+"_baseline_unchanged",a.at("phase_counts")==b.at("phase_counts")&&a.at("measurement_phase_counts")==b.at("measurement_phase_counts"));}
  rows.push_back({{"mode",a.at("mode")},{"offset",a.at("offset")},{"control",a.at("control")},{"phases",phases},{"measurement_phases",measured},{"body_frames_before",bbody},{"body_frames_after",abody},{"normal_tail_completions",normal},{"tail_confirmations",tail_confirmed},{"cancellations",cancelled}});
 }
 J out={{"schema","pas.prelive-family-verification.v1"},{"assertions",checks.size()},{"failed",failed},{"checks",checks},{"results",rows},{"software_evidence_valid",failed==0},{"windows_cost_qualified",false},{"physical_gold",0}};std::ofstream f(argv[3]);f<<out.dump(2)<<'\n';if(!f)throw std::runtime_error("report write");std::cout<<"family verification="<<checks.size()<<" failed="<<failed<<'\n';return failed?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
